{
  "root_causes": [
    {
      "service": "ts-preserve-service",
      "fault_kind": "http_response_body_corrupted",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, c.span_name cspan, s.service_name callee, s.span_name sspan, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) c_err, sum(CASE WHEN s.attr_status_code='Error' THEN 1 ELSE 0 END) s_err, any_value(c.attr_http_response_status_code) cst, any_value(s.attr_http_response_status_code) sst FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id AND s.trace_id = c.trace_id WHERE c.service_name = 'ts-preserve-service' AND c.attr_span_kind='Client' GROUP BY 1,2,3,4 ORDER BY n DESC",
          "claim": "Preserve's POST to ts-seat-service arrives as 'GET /error' with status 405 on 806 calls, all errored; other preserve callees are clean."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) caller_err, sum(CASE WHEN s.attr_status_code='Error' THEN 1 ELSE 0 END) callee_err, any_value(c.attr_http_response_status_code) st FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id AND s.trace_id = c.trace_id WHERE c.service_name='ts-ui-dashboard' AND s.service_name='ts-preserve-service' AND s.span_name LIKE '%preserve%' GROUP BY 1,2",
          "claim": "Dashboard calls to preserve's preserve endpoint: 602 of 807 failed with status 500 at the user-facing tier."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, message, count(*) n FROM abnormal_logs WHERE service_name = 'ts-seat-service' AND level = 'WARN' GROUP BY 1,2,3",
          "claim": "Seat service logs 806 warnings 'Request method GET not supported', matching the rewritten preserve requests."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) caller_err, sum(CASE WHEN s.attr_status_code='Error' THEN 1 ELSE 0 END) callee_err, any_value(c.attr_http_response_status_code) st FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id AND s.trace_id = c.trace_id WHERE c.service_name='ts-ui-dashboard' AND s.service_name='ts-preserve-service' AND s.span_name LIKE '%preserve%' GROUP BY 1,2",
          "claim": "Preserve's 500 responses surface at ts-ui-dashboard, where 602 of 807 preserve calls failed."
        }
      ]
    }
  ]
}
